import sys

DIGITS = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"

def to_base(num, base):
    if num == 0:
        return "0"
    digits = []
    while num > 0:
        digits.append(DIGITS[num % base])
        num //= base
    return ''.join(reversed(digits))

for line in sys.stdin:
    line = line.strip()
    if not line:
        continue
    sb, tb, s = line.split()
    sb = int(sb)
    tb = int(tb)
    num = int(s, sb)
    print(to_base(num, tb))

