import sys

def factorize(b):
    factors = {}
    d = 2
    while d * d <= b:
        while b % d == 0:
            factors[d] = factors.get(d, 0) + 1
            b //= d
        d += 1
    if b > 1:
        factors[b] = factors.get(b, 0) + 1
    return factors

def legendre(n, p):
    count = 0
    power = p
    while power <= n:
        count += n // power
        power *= p
    return count

for line in sys.stdin:
    line = line.strip()
    if not line:
        continue
    n, b = map(int, line.split())
    factors = factorize(b)
    if n == 0:
        print(0)
        continue
    ans = min(legendre(n, p) // e for p, e in factors.items())
    print(ans)

