import sys

PAIRS = {')': '(', ']': '[', '}': '{'}
OPENERS = set(PAIRS.values())

def is_balanced(s):
    stack = []
    for c in s:
        if c in OPENERS:
            stack.append(c)
        elif c in PAIRS:
            if not stack or stack.pop() != PAIRS[c]:
                return False
    return not stack

for line in sys.stdin:
    s = line.rstrip('\n')
    if s == 'END':
        break
    print('Yes' if is_balanced(s) else 'No')

