import sys

def main():
    data = sys.stdin.read().split('\n')
    idx = 0
    out = []
    field_no = 0
    while idx < len(data):
        line = data[idx].strip()
        idx += 1
        if line == '':
            continue
        n, m = map(int, line.split())
        if n == 0 and m == 0:
            break
        grid = [data[idx + r] for r in range(n)]
        idx += n
        field_no += 1
        if field_no > 1:
            out.append('')
        out.append(f"Field #{field_no}:")
        for r in range(n):
            row_out = []
            for c in range(m):
                if grid[r][c] == '*':
                    row_out.append('*')
                else:
                    cnt = 0
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            if dr == 0 and dc == 0:
                                continue
                            rr, cc = r + dr, c + dc
                            if 0 <= rr < n and 0 <= cc < m and grid[rr][cc] == '*':
                                cnt += 1
                    row_out.append(str(cnt))
            out.append(''.join(row_out))
    print('\n'.join(out))

main()

