import sys

ROWS = ["qwertyuiop[]", "asdfghjkl;'", "zxcvbnm,./"]

def decode_char(c):
    if c == ' ':
        return ' '
    lower = c.lower()
    for row in ROWS:
        pos = row.find(lower)
        if pos != -1:
            return row[pos - 2]
    return c

def main():
    text = sys.stdin.readline().rstrip('\n')
    print(''.join(decode_char(c) for c in text))

main()

