import sys

def c_mod(a, m):
    q = abs(a) // m
    if a < 0:
        q = -q
    return a - q * m

def sort_key(num, m):
    r = c_mod(num, m)
    if num % 2 != 0:
        return (r, 0, -num)
    return (r, 1, num)

def main():
    data = sys.stdin.read().split()
    idx = 0
    out = []
    while True:
        n = int(data[idx]); m = int(data[idx + 1]); idx += 2
        if n == 0 and m == 0:
            out.append("0 0")
            break
        nums = [int(data[idx + i]) for i in range(n)]
        idx += n
        nums.sort(key=lambda x: sort_key(x, m))
        out.append(f"{n} {m}")
        out.extend(str(x) for x in nums)
    print('\n'.join(out))

main()

