import sys
from collections import deque

def main():
    data = sys.stdin.read().split('\n')
    idx = 0
    out = []
    while idx < len(data):
        line = data[idx].strip()
        idx += 1
        if line == '':
            continue
        k, m = map(int, line.split())
        if k == 0:
            break
        q = deque()
        for _ in range(m):
            parts = data[idx].split()
            idx += 1
            cmd = parts[0]
            if cmd == 'ENQUEUE':
                if len(q) >= k:
                    out.append('full')
                else:
                    q.append(parts[1])
            elif cmd == 'DEQUEUE':
                out.append(q.popleft() if q else 'empty')
            elif cmd == 'FRONT':
                out.append(q[0] if q else 'empty')
    print('\n'.join(out))

main()

