import sys

REV = {
    'A': 'A', 'H': 'H', 'I': 'I', 'M': 'M', 'O': 'O', 'T': 'T', 'U': 'U', 'V': 'V',
    'W': 'W', 'X': 'X', 'Y': 'Y', '1': '1', '8': '8', 'J': 'L', 'L': 'J', 'S': '2',
    '2': 'S', 'Z': '5', '5': 'Z', 'E': '3', '3': 'E',
}

def main():
    out = []
    for line in sys.stdin:
        s = line.strip()
        if not s:
            continue
        is_pal = s == s[::-1]
        n = len(s)
        mirrored = True
        for i in range(n):
            rc = REV.get(s[i], '')
            if rc == '' or rc != s[n - 1 - i]:
                mirrored = False
                break
        if is_pal and mirrored:
            desc = 'is a mirrored palindrome.'
        elif is_pal:
            desc = 'is a regular palindrome.'
        elif mirrored:
            desc = 'is a mirrored string.'
        else:
            desc = 'is not a palindrome.'
        out.append(f"{s} -- {desc}")
        out.append('')
    print('\n'.join(out))

main()

