def main():
    data = sys.stdin.read().split('\n')
    idx = 0
    while data[idx].strip() == '':
        idx += 1
    n = int(data[idx].strip()); idx += 1
    out = []
    for case in range(n):
        while data[idx].strip() == '':
            idx += 1
        s = data[idx].strip(); idx += 1
        L = len(s)
        period = L
        for k in range(1, L + 1):
            if L % k == 0 and s[:k] * (L // k) == s:
                period = k
                break
        if case > 0:
            out.append('')
        out.append(str(period))
    print('\n'.join(out))

