def main():
    out = []
    for line in sys.stdin:
        s = line.rstrip('\n')
        last = {}
        start = 0
        best = 0
        for i, c in enumerate(s):
            if c in last and last[c] >= start:
                start = last[c] + 1
            last[c] = i
            best = max(best, i - start + 1)
        out.append(str(best))
    print('\n'.join(out))

