def main():
    out = []
    for line in sys.stdin:
        s = line.strip()
        if not s:
            continue
        open_needed = 0
        close_needed = 0
        for c in s:
            if c == '(':
                open_needed += 1
            elif open_needed > 0:
                open_needed -= 1
            else:
                close_needed += 1
        out.append(str(open_needed + close_needed))
    print('\n'.join(out))

