import sys

def main():
    out = []
    for line in sys.stdin:
        tokens = line.strip().split()
        if not tokens:
            continue
        stack = []
        for tok in reversed(tokens):
            if tok in '+-*/':
                a = stack.pop()
                b = stack.pop()
                if tok == '+':
                    stack.append(a + b)
                elif tok == '-':
                    stack.append(a - b)
                elif tok == '*':
                    stack.append(a * b)
                else:
                    stack.append(a // b)
            else:
                stack.append(int(tok))
        out.append(str(stack[-1]))
    print('\n'.join(out))

main()

